insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('20a1f0bb-1979-46f7-a7d5-4e2b03ff6c82','en','dae-han-min-guk-clap-chant','Dae-Han-Min-Guk Clap Chant','Dae-Han-Min-Guk Clap Chant is the iconic call-and-clap cheer led by the Red Devils during the 2002 World Cup.','During the 2002 Korea-Japan World Cup, the Red Devils supporters'' group led the crowd in the ''Dae~Han-Min-Guk (clap clap-clap clap-clap)'' chant, which spread nationwide as the signature World Cup cheer. It was originally a variation of the Suwon Samsung Bluewings supporters'' chant ''Su~won Samsung,'' repurposed for the national team during the World Cup.','The chant is believed to derive from the Suwon Samsung Bluewings supporters group Grand Blue''s cheer, ''Su~won Samsung (clap-clap-clap-clap-clap).'' Around 1997, football supporters from around the country came together to form the Red Devils and adapted the four-syllable chant to the national team as ''Dae~Han-Min-Guk.'' During the 2002 Korea-Japan World Cup it exploded in popularity as the symbolic chant of street cheering, becoming almost like a national greeting, and it was even included on a track from the official World Cup album. The chant''s copyright was later disputed by the late musician Shin Hae-chul, sparking controversy.','Can be used as-is as a clap chant when cheering for the national team.',null,array['대한민국 짝짝짝짝짝','Dae~Han-Min-Guk','clap-clap-clap chant'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('246fd9fb-bbf4-4dd9-af6b-0c1430ecafeb','en','overwatch-c9-cloud9','Overwatch C9 (Cloud9)','C9 is Overwatch slang for losing a fight you''ve already won by failing to contest the objective.','Originally short for the pro esports team Cloud9, in the Korean Overwatch community the term became fixed slang for a situation where a team wins a team fight but then loses anyway by failing to stick to the point or payload. It started as a joke in Twitch chat, but by around 2018, when the Overwatch League launched, it had become a semi-official term used by players and casters alike.','Korean Overwatch community slang, made semi-official around the launch of the Overwatch League (2018).','Used when a team carelessly throws away a match it had already won.',null,array['오버워치 씨나인(C9)','C9','안비벼서 씨나인'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('37113ce0-9c41-44a6-94c6-f0477d2e2e81','en','rollin-challenge','Rollin'' Challenge','The Rollin'' Challenge is a TikTok dance trend that spread after Brave Girls'' ''Rollin'''' went viral four years after release.','A compilation video of comments on the 2017 song ''Rollin'''' went viral online, sending it back up the music charts in February 2021. Members Yujeong, Eunji, and Yuna spread the trend further by posting challenge videos on TikTok. The moment became a landmark in K-pop chart history as a symbol of a delayed hit''s comeback.','Started in February-March 2021 when Brave Girls members posted challenge videos on TikTok, fueled by the spread of a fan-made comment compilation video.','Cited when talking about a delayed hit or ''rediscovery'' success story.',null,array['롤린 챌린지','브레이브걸스 역주행'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('5371a917-e55b-4f3b-b47a-4510f03b8180','en','baby-vox-ya-ya-ya','Baby V.O.X - ''Ya Ya Ya''','''Ya Ya Ya'' is Baby V.O.X''s 1998 title track, known for its powerful choreography.','''Ya Ya Ya,'' the title track of Baby V.O.X''s second album released in 1998, became a huge hit thanks to choreography far more powerful than the song''s tone suggested, and it cemented the group''s image as a ''girl group that could really dance.''','''Ya Ya Ya'' was the title track of Baby V.O.X''s second album, released in 1998; its choreography, dubbed the ''Annyeong (Hello) Dance'' and created by choreographer Lee Young-hwan (who had also coached Steve Yoo), alternated between girlish moves and intense movements, resonating strongly with fans. The members reportedly trained up to 8 hours a day and even studied taekkyeon for three months to master the routine. The stage cemented Baby V.O.X''s image as a ''girl group that could really dance.''','Can be cited as a landmark example of late-1990s girl group choreography.',null,array['베이비복스 ''야야야''','야야야'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('56e5c678-6b84-43de-af88-1bbd8c63f4d8','en','because-its-slippery','Because It''s Slippery (Mikkeureoun-ikka)','''Because it''s slippery'' is a catchphrase from comedian Rimario''s character on the ''Pigeon Choir'' segment of Wootchasa.','Rimario, active on the sketch comedy show Wootchasa, became popular for catchphrases like ''because it''s slippery'' and ''true to instinct.'' It''s often confused with Gag Concert''s ''Because I know the feeling'' (2013), but the two are catchphrases from different shows and different eras.','Aired from 2004 to 2005 on the ''Pigeon Choir'' segment of SBS''s Wootchasa.','Cited in retrospective content about mid-2000s network comedy.','Should not be confused with ''Because I know the feeling'' (Gag Concert, 2013).',array['미끄러우니까','리마리오'],'[{"text": "Watch out, it''s slippery lol", "situation": "KakaoTalk"}, {"text": "Haven''t heard this catchphrase in a while", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('585450b8-2607-4744-866a-2c866011fc8f','en','gods-childcare-diary-jaemin','god''s Childcare Diary - Jaemin','god''s Childcare Diary is an observational variety segment where the members of god cared for 22-month-old baby Jaemin, and the moment they became a ''nation''s group.''','Airing on MBC from January 2000, this program is regarded as an early forerunner of observational variety shows, following the members of god as they cared for one-year-old Han Jaemin. It became a sensation, with fans even sending rice and side dishes after seeing the members skip meals, and it was the decisive moment that turned god into a ''nation''s group.''','Began airing in January 2000 as a segment of MBC''s ''Sunday Sunday Night'' and ''Saturday Achievement.''','Referenced when discussing the origins of observational variety shows.',null,array['god의 육아일기 - 재민이','재민이','god 육아일기'],'[{"text": "This childcare variety show totally gives Jaemin-era vibes", "situation": "KakaoTalk"}, {"text": "That''s the show that made god a nation''s group", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('68a57d13-74b1-4cc7-8866-028ec23a30e6','en','infinite-challenge-delivery-special','Infinite Challenge: Delivery Special (Baedal-ui Mudo)','Delivery Special is an Infinite Challenge special in which the members scattered across the globe to complete delivery missions for the 70th anniversary of Korea''s liberation.','This special aired over episodes 433, 441, and 443-445 of Infinite Challenge in 2015. Originally planned as a punishment mission based on a viewer poll, it was expanded into a special marking the 70th anniversary of Korea''s liberation. Members scattered to Africa, North America, South America, Asia, and Europe to complete delivery missions, sponsored by delivery app Baedal Minjok (Baemin), which even matched the caption color and font to its brand. One installment, ''The Secret of Hashima Island,'' won a special award at the Amnesty International Media Awards.','Began airing June 20, 2015 as episode 433 of MBC''s Infinite Challenge, sponsored by Baedal Minjok (Baemin).','Often cited as an example of variety TV combining a public-interest campaign with brand sponsorship.',null,array['배달의 무도','무도 배달의 무도','무한도전 배달의민족 특집'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('73b417c4-092c-4632-b57b-ebbfeb49a8ef','en','made-in-heaven-cheonsaeng-yeonbun','Made in Heaven (Cheonsaeng Yeonbun)','Made in Heaven is a couple-matching variety show that kicked off the 2002 matchmaking-show boom.','A couple-matching variety show that began on MBC in October 2002, it paired celebrities up front and then had them play games together, rather than having them choose partners, launching the 2000s matchmaking-variety-show boom.','Started in June 2002 as a segment of MBC''s weekend variety show ''Saturday Achievement,'' before becoming an independent program on October 26 of that year, with Kang Ho-dong hosting under his own name for the first time. The format showed celebrity men and women becoming couples through games and conversation, and unlike earlier dating shows aimed at ordinary people, such as ''Youth Date'' and ''Studio of Love,'' it drew popularity by highlighting the celebrities'' human side. It is regarded as the forerunner of the matchmaking and couple-matching variety genre that followed.','Cited as an example of the 2000s matchmaking-variety-show boom.',null,array['천생연분','강호동의 천생연분'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('7da74a63-c3b3-4017-ba91-3c97071c1349','en','park-ji-sung-national-team-retirement-2011','Park Ji-sung''s National Team Retirement (2011)','Park Ji-sung''s National Team Retirement marks the moment he stepped away from Korea''s national football team after the 2011 Asian Cup semifinal.','Park Ji-sung earned his 100th national team cap in the 2011 AFC Asian Cup semifinal against Japan, then announced his retirement from the national team, which he had represented for 11 years, at an official press conference on January 31, after the tournament ended. He and Lee Young-pyo retired around the same time, marking the end of an era. He later named not stepping up as a penalty kicker in that match, due to a trauma from past shootouts, as his biggest regret, saying he left the burden to his younger teammates.','Park Ji-sung''s announcement of his national team retirement after the conclusion of the 2011 AFC Asian Cup.','Frequently cited as the retirement story of a Korean football legend.',null,array['박지성 국가대표 은퇴 (2011)'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('8310543f-7e46-4af8-bec4-039e4482cb25','en','onigiri-dance','Onigiri Dance','The Onigiri Dance is a character dance-animation meme created by a Korean animation YouTuber team.','The trend began when the Korean animation YouTuber team VIVINOS uploaded an animated dance video titled ''Onigiri Dance'' in October 2021. By 2022 it had become one of the leading dance memes on TikTok and YouTube Shorts alongside the Zero Two dance and Uncle John dance, spawning numerous parodies.','The animation ''Onigiri Dance'' by YouTuber team VIVINOS (uploaded October 2021, spread widely in 2022).','A cute animation-style dance meme, good for lighthearted content.',null,array['오니기리 댄스'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('83498de5-7e47-4571-ab44-59c54ffc311b','en','chung-ju-yung-cattle-drive-to-north-korea','Chung Ju-yung''s Cattle Drive to North Korea','Chung Ju-yung''s Cattle Drive to North Korea refers to the moment Hyundai founder Chung Ju-yung led 1,001 cattle across the border at Panmunjom.','In June and October 1998, Hyundai Group honorary chairman Chung Ju-yung crossed Panmunjom into North Korea twice, leading 1,001 head of cattle each time - a symbolic scene broadcast live by outlets including CNN. Tied to Chung''s personal history as a refugee from the North, the event is still recalled as one of the defining images of inter-Korean exchange.','Hyundai Group honorary chairman Chung Ju-yung''s visits to North Korea (June 16 and October 1998).','Cited as a metaphor for a bold decision or an extravagant gesture.',null,array['정주영 소떼 방북','소떼 방북','왕회장 소떼'],'[{"text": "This scale is basically Chung Ju-yung''s cattle drive level", "situation": "KakaoTalk"}, {"text": "That''s 1,001-cattle-herd levels of decisiveness", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('93540117-5cc6-4236-9b0c-20caa7d5a9d2','en','croffle','Croffle','A croffle is a croissant-waffle hybrid dessert made by pressing croissant dough in a waffle iron.','Made by pressing frozen croissant dough in a waffle iron, the croffle - a portmanteau of ''croissant'' and ''waffle'' - has a crisp exterior while keeping the flaky, layered texture inside. Fueled by the home-baking boom, countless recipe videos featuring toppings like cream cheese, Nutella, and maple syrup flooded social media, and the dessert also became a staple on cafe menus.','Reviews of croffle spots began increasing on social media and blogs from mid-2019, and as home baking surged in 2020 during COVID-19, croffles made at home with waffle irons became a centerpiece of Korea''s dessert trends.','Mentioned when introducing home baking or simple dessert recipes.',null,array['크로플','크로플만들기'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9b686d48-42e9-448c-b116-164fe7e535e1','en','yes-ive-decided','Yes, I''ve Decided!','''Yes, I''ve decided!'' is a national catchphrase born from the 1994 segment ''Theater of Life.''','In the 1994 ''Theater of Life'' segment of MBC''s ''Sunday Sunday Night,'' host Lee Hwi-jae would declare this line while picking between two choices; it went on to become a nationwide catchphrase used whenever someone makes up their mind. It surged in popularity again after the segment was rerun in 1997.','MBC''s ''Sunday Sunday Night'' segment ''Theater of Life'' (1994).','Still used today to playfully emphasize a moment of decision.',null,array['그래 결심했어','인생극장 유행어'],'[{"text": "Yes, I''ve decided! We''re watching this movie tonight", "situation": "KakaoTalk"}, {"text": "Made my decision, Theater-of-Life style", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('b429570f-5de0-4910-8048-8879e6be7455','en','son-dam-bi-crazy-chair-dance','Son Dam-bi''s ''Crazy'' Chair Dance','The chair dance from Son Dam-bi''s 2008 hit ''Crazy'' swept variety TV that year.','The chair dance from Son Dam-bi''s ''Crazy'' (Michyeosseo), released in September 2008, became a sensation, with celebrity after celebrity - starting with Heo Yi-jae - imitating it on variety shows; it grew so popular that broadcasters reportedly issued in-house ''Crazy bans'' to curb it.','Choreography from the title track of Son Dam-bi''s second mini album, said to be inspired by dance moves seen at American gay clubs.','Referenced as a parody number for company dinners or talent shows.',null,array['손담비 미쳤어 의자춤','미쳤어 토끼춤','손담비 의자춤'],'[{"text": "Got the chair dance ready for the dinner talent show lol, might trigger a Crazy ban", "situation": "work group chat"}, {"text": "Son Dam-bi''s chair dance is still legendary", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('b8c3856f-a3e9-4025-8d83-da8445bd3592','en','thats-it-my-feelings-are-hurt-sensitivity','That''s It! My Feelings Are Hurt! (Sensitivity)','''That''s it! My feelings are hurt!'' is a catchphrase from a Gag Concert character who sulks at the slightest slight.','In the 2011 Gag Concert segment ''Sensitivity,'' the barbarian character played by Kim Ji-ho became popular for a recurring pattern of pouting over the smallest offense, declaring ''That''s it! My feelings are hurt! I''m going home!'' Despite its wartime setting, the sketch got laughs through a strikingly modern, sensitive character.','2011 KBS Gag Concert segment ''Sensitivity,'' a line delivered by comedian Kim Ji-ho.','Used affectionately to tease someone who is being overly sensitive.',null,array['됐어! 나 빈정 상했어!(감수성)','감수성 오랑캐','빈정상했어'],'[{"text": "That''s it! My feelings are hurt! I''m going home lol", "situation": "KakaoTalk"}, {"text": "That reaction is totally ''Sensitivity''-style sulking", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('bcabc258-86b7-4674-8430-49fd1b8375ef','en','2026-is-the-new-2016','2026 Is the New 2016','''2026 is the new 2016'' is a meme expressing nostalgia for the simpler feel of 2016 amid today''s overly polished social media.','As short-form video and social media content has come to feel excessively polished and repetitive, this meme captures a longing for the simpler, more spontaneous mood of around 2016. Gen Z users who experienced 2016 firsthand share old photos and videos from that time to express nostalgia for ''when things were better.'' Mentions of the meme have grown on social media and online communities through 2026.','Emerged out of fatigue with the overly edited social media content of 2026.','Used to contrast with today''s overly produced content.',null,array['2026 이즈 더 뉴 2016'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('d722373f-cdad-4980-bd2a-6375de65c229','en','hwani-jini','Hwani-Jini','Hwani-Jini was the longest-running segment of Pokso Club, known for its ''mix concert'' format blending two songs into one.','Hwani-Jini featured a ''mix concert'' format in which two unrelated songs (for example, Park Sang-min''s ''Sunflower'' and the Beatles'' ''Let It Be'') were sung back to back as if they were a single song. It was the signature long-running segment of Pokso Club, Korea''s first stand-up comedy show.','Aired from Pokso Club''s premiere on November 1, 2002, until August 2005.','Referenced as the originator of the song-mashup comedy format.',null,array['화니지니','폭소클럽 화니지니'],'[{"text": "This song mashup is total Hwani-Jini style", "situation": "KakaoTalk"}, {"text": "The original mix-concert format is Hwani-Jini", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('d98e52dc-7e9e-4f33-a91f-888ad7676f23','en','g-dragon-home-sweet-home-challenge','G-Dragon Home Sweet Home Challenge','The Home Sweet Home Challenge reimagines Taeyang''s on-stage fall during G-Dragon''s ''HOME SWEET HOME'' performance as intentional choreography.','During a performance of G-Dragon''s ''HOME SWEET HOME,'' Taeyang tripped and fell while dancing; fans turned the moment into a challenge by recreating the fall exactly, joking that ''this wasn''t a mistake - it was the choreography all along.'' G-Dragon himself joined in, posting a compilation of challenge videos on his own social media and commenting, ''just do it like you''re willing to bust a knee.''','Fans reinterpreted Taeyang''s on-stage fall during G-Dragon''s ''HOME SWEET HOME'' performance as if it were choreography.','Used for content that plays off a mistake as if it were intentional, in a witty way.',null,array['지드래곤 홈 스윗 홈 챌린지','무릎 깨져도 챌린지'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('e105d72c-4f1a-454b-999a-e95ec71207a6','en','infinite-challenge-butterfly-effect','Infinite Challenge: Butterfly Effect','The Butterfly Effect special used a skit set in the Maldives and the Arctic to illustrate the butterfly effect of global warming.','This special aired as episode 228 of Infinite Challenge on December 18, 2010, sponsored by Korea''s Ministry of Environment, to dramatize the seriousness of global warming through the metaphor of the butterfly effect. In the skit, the ''Maldives'' team discovers water leaking from the ceiling and calls to complain to the ''Arctic'' team, when in fact the Maldives team had turned on air conditioning that melted their own ice, while in the Arctic, a collapsing Jenga tower led them to mistakenly believe the Maldives team was deliberately spilling water.','Episode 228 of MBC''s Infinite Challenge, aired December 18, 2010, sponsored by the Ministry of Environment as part of a road-address-system promotion.','Notable for having been reused as environmental education material.',null,array['무한도전 나비효과','무도 나비효과 특집'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('e113df5f-99d8-41fc-a47b-8f030a4f0791','en','god-to-mother-eomeonim-kke','god - ''To Mother'' (Eomeonim-kke)','''To Mother'' is god''s signature ballad from their 3rd album, famous for its ''jajangmyeon'' lyric about filial devotion.','The title track of god''s third studio album, based on a true story from leader Park Joon-hyung''s childhood. The line ''Mother said she didn''t like jajangmyeon'' struck a deep chord with listeners and turned the song into a ballad the whole country could sing along to; the line is still parodied and quoted in content about filial devotion today.','Released July 25, 2000 as the title track of god''s third studio album, ''Chapter 3.''','The lyric is quoted when discussing love for one''s parents or filial devotion.',null,array['god - 어머님께','짜장면이 싫다고 하셨어'],'[{"text": "Thinking of my parents, I listened to god''s ''To Mother'' again", "situation": "KakaoTalk"}, {"text": "I still cry every time I hear the ''jajangmyeon'' lyric", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
